/**
 * Wraps a screenshot in an SVG monitor bezel + stand, for images that show the
 * app filling an entire external display with no window chrome of its own
 * (full-screen video, a full-screen page, a slideshow). Without this the
 * screenshot alone doesn't read as "on a monitor" ,  it's just a photo.
 *
 * The markup and class names here are mirrored in scripts/import-content.mjs
 * for the same handful of image names inside imported article HTML
 * (figure.is-fullscreen), styled by the shared .device-frame rules in
 * index.css. Keep both in sync if the bezel geometry changes.
 */
export default function DisplayFrame({ children, className = '' }) {
  return (
    <span className={`device-frame ${className}`.trim()}>
      <svg className="device-frame-chrome" viewBox="0 0 320 200" preserveAspectRatio="none" aria-hidden="true" focusable="false">
        <rect x="0" y="0" width="320" height="184" rx="3" className="device-frame-bezel" />
        <path d="M146 184 L141 197 L179 197 L174 184 Z" className="device-frame-neck" />
        <rect x="118" y="196" width="84" height="4" rx="2" className="device-frame-base" />
      </svg>
      <span className="device-frame-screen">{children}</span>
    </span>
  );
}
